/** Rol del alimento en un plato — se usa para el botón "Sustituir" */
export type FoodRole = 'protein' | 'carb' | 'veg' | 'fruit' | 'fat' | 'dairy' | 'nut' | 'other'

export type PortionState = 'raw' | 'cooked'

export interface Portion {
  label: string
  g: number
  /** Solo para alimentos con variante cruda y cocinada */
  state?: PortionState
}

export interface CuratedFood {
  id: string
  name: string
  emoji: string
  cat: FoodCategory
  role: FoodRole
  /** NDB USDA del alimento (crudo, o único si no hay variante cocinada) */
  ndb?: number
  /** NDB USDA de la variante cocinada (opcional) */
  ndbCooked?: number
  /** Código CIQUAL si el alimento no existe en USDA (ver también foods.ciqual.ts) */
  ciq?: number
  ciqCooked?: number
  /** peso cocinado ÷ peso crudo (solo si hay variante cocinada) */
  yield?: number
  portions: Portion[]
  allergens?: Allergen[]
  aliases?: string[]
  /** Etiquetas de estilo: 'rapido', 'proteico', etc. */
  tags?: string[]
  /** Unidad de compra (para la lista): "6 huevos", "3 plátanos"… */
  unit?: ShopUnit
}

export interface ShopUnit { one: string; many: string; g: number }
const U = (one: string, many: string, g: number): ShopUnit => ({ one, many, g })

const P = (label: string, g: number, state?: PortionState): Portion => ({ label, g, state })
const R = (label: string, g: number) => P(label, g, 'raw')
const C = (label: string, g: number) => P(label, g, 'cooked')

